import{_ as o,h as E,i as e,c as r,v as t,p as n,x as l,m as p,e as s,S as d}from"./chunks/framework.Dvtg8yj2.js";const _=JSON.parse('{"title":"PII 去除","description":"","frontmatter":{"title":"PII 去除","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/pii-redact.md","filePath":"llm/pii-redact.md","lastUpdated":1788454257000}'),I={name:"llm/pii-redact.md"};function P(h,a,c,A,m,B){const i=E("Mermaid");return e(),r("div",null,[a[1]||(a[1]=t('<h1 id="pii-去除" tabindex="-1">PII 去除 <a class="header-anchor" href="#pii-去除" aria-label="Permalink to &quot;PII 去除&quot;">​</a></h1><div class="epigraph"><p>预训练语料里的电子邮箱、电话与证件号会被模型当成要记忆的字符串；清洗要把可识别个人的跨度拿掉或替换，而不把所有专有名词从语言里剜走。</p><footer>—— 综合 C4、Dolma 与常见 PII 识别实践</footer></div><p>网页与论坛包含大量个人可识别信息（PII）：邮箱、电话、身份证号、银行卡、IP、住址，有时还有完整的简历粘贴。语言模型会记忆重复出现的字符串，服务阶段可能被套出。Raffel 等人的 C4 已用正则丢掉部分邮箱与电话；后来的 Dolma 等配方把 PII 当成与质量、毒性并列的一层。本篇写去除的对象、检测手段与替换策略。它不是安全过滤：一篇无攻击性的招聘帖仍可能含手机号。也不是去重：同一条 PII 出现一次就值得处理。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PII 没有单一形式语言。邮箱与 URL 可用正则；电话有国家码、分机、把数字写成汉字的变体；证件与银行卡有校验位，但也有故意写错的示例；人名与住址则几乎只能靠命名实体识别，且与新闻里的公众人物、百科条目冲突。召回不足，模型仍会背出用户隐私；精确率不足，模型学不到「谁在何处做了什么」——历史、地理、代码里的示例邮箱（<code>user@example.com</code>）会被误杀。</p><p>训练与服务的目标也不同。训练侧希望梯度看不到真实手机号，但仍希望看到「联系方式」这类语言现象，因此常用占位符替换。服务侧对用户输入的 PII 可能要另做日志脱敏，那是产品合规，不是语料管道。本篇只讨论进入预训练（及常一并处理的指令数据）之前的文本改写。法律定义因地而异，工程上应把类别表写成配置：至少覆盖联系方式、政府标识、支付账号，再决定是否对人名、精确地理坐标下手。</p><h3 id="结构化模式与开放实体" tabindex="-1">结构化模式与开放实体 <a class="header-anchor" href="#结构化模式与开放实体" aria-label="Permalink to &quot;结构化模式与开放实体&quot;">​</a></h3><p>第一类 PII 是结构化的：邮箱、URL 中的查询参数、IMEI、信用卡（Luhn 校验可降假阳性）、部分国家的身份证正则。这类应用正则加校验，假阳性相对可控。第二类是开放实体：人名、电话口语、住址。NER 模型在新闻上训练，搬到论坛会把昵称当真人，或把「张三丰」这类文学人物当 PII。第三类是准标识符组合：单独的邮编或年龄不是 PII，与姓名、学校拼在一起就是。管道很难穷尽第三类，通常用「高召回结构化 + 保守 NER」覆盖前两类，并承认准标识符要靠抽样审计而不是宣称清零。</p><p><span class="marginnote">「去掉 PII」若实现成「删掉整页」，会把含一句联系方式的高质量教程整篇丢掉，对小语种尤其伤。优先改写跨度：把匹配换成 <code>&lt;EMAIL&gt;</code> 一类特殊 token 或固定假邮箱，页仍可学。只有当页的主体就是个人信息倾倒时，才整页丢弃。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>管线位置应在正文抽取与语言识别之后、去重前后皆可，但要固定下来：去重键若按原文算，脱敏后重复结构会变，可能让镜像页逃过去。更稳的是：规范化与 PII 改写之后再算精确哈希与 MinHash。步骤上：对结构化模式跑正则；对信用卡等做校验再替换；对人名/地址跑 NER 或启发式（「我住在」后接数字+路）；用统一占位符替换匹配跨度，避免用随机替换引入新的「看起来真」的假号码——模型仍可能把假号码当事实。占位符应进入 tokenizer 词表或保证能被切开，不要变成训练时从未见过的碎字符。</p><p>C4 公开描述包含删除含某些邮箱与电话模式的行或页，策略偏丢弃。Dolma 一类后来工作更强调检测器与文档级政策。实践中应用分层：高置信结构化匹配做替换；NER 低置信只记日志或抽样；命中密度超过阈值（例如一页里数十个电话）则整页丢弃，因其更像数据泄漏或垃圾目录。不要在 mapper 里调用外部付费 API 做全量 NER，成本与隐私都不合适；用本地小模型或规则。代码仓库里的密钥、AWS 密钥模式也常并入同一层，尽管严格说是秘密而不是个人——对预训练同样有害。</p><h3 id="替换、删除与哈希" tabindex="-1">替换、删除与哈希 <a class="header-anchor" href="#替换、删除与哈希" aria-label="Permalink to &quot;替换、删除与哈希&quot;">​</a></h3><p>替换：跨度变成类型占位符，保留句法。删除：跨度消失，左右词粘连，可能制造不通句子。哈希：同一邮箱始终映到同一假名，能保留「这个作者多次出现」的共指，但也保留可链接性，对隐私更弱。预训练一般选类型占位符（所有邮箱同一 token）或删除；需要共指的对话数据再考虑一致性假名。无论哪种，必须在数据卡写明，并保证验证集与训练集同一政策，否则评测里的实体题会失真。</p>',14)),(e(),n(d,null,{default:l(()=>[s(i,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E6%8A%BD%E5%8F%96%E5%B9%B6%E8%A7%84%E8%8C%83%E5%8C%96%E5%90%8E%E7%9A%84%E6%96%87%E6%A1%A3%22%5D%20--%3E%20R%5B%22%E7%BB%93%E6%9E%84%E5%8C%96%E6%AD%A3%E5%88%99%20%2B%20%E6%A0%A1%E9%AA%8C%22%5D%0A%20%20D%20--%3E%20N%5B%22NER%20%2F%20%E4%BF%9D%E5%AE%88%E4%BA%BA%E5%90%8D%E5%9C%B0%E5%9D%80%22%5D%0A%20%20R%20--%3E%20P%5B%22%E5%8D%A0%E4%BD%8D%E7%AC%A6%E6%9B%BF%E6%8D%A2%22%5D%0A%20%20N%20--%3E%20P%0A%20%20P%20--%3E%20DEN%5B%22%E5%91%BD%E4%B8%AD%E5%AF%86%E5%BA%A6%22%5D%0A%20%20DEN%20--%3E%20KEEP%5B%22%E4%BF%9D%E7%95%99%E6%94%B9%E5%86%99%E5%90%8E%E6%96%87%E6%A1%A3%22%5D%0A%20%20DEN%20--%3E%20DROP%5B%22%E6%95%B4%E9%A1%B5%E4%B8%A2%E5%BC%83%22%5D%0A%20%20KEEP%20--%3E%20H%5B%22%E5%86%8D%E5%8E%BB%E9%87%8D%22%5D%0A%20%20DROP%20--%3E%20X%5B%22%E4%B8%8D%E8%BF%9B%E8%AE%AD%E7%BB%83%E9%9B%86%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>记忆机制解释为什么值得做。重复的邮箱、电话在语料中往往来自页脚模板或作者签名，出现次数远高于普通 n-gram，梯度会把它们压进参数。推理时给一段前缀「联系作者：」就可能续出真实字符串。改成占位符后，模型学到的是槽位，而不是某个具体账号。校验位机制降低假阳性：随机 16 位数字不会都当成信用卡，减少对订单号、哈希的误伤。NER 机制是上下文分类，阈值高则漏人名，阈值低则杀城市名与机构名；所以人名策略往往只在「明确的联系上下文」触发，而不是对所有 PERSON 标签动手。</p><p>与安全过滤的机制不同：安全看的是内容类别，PII 看的是标识符跨度。一篇安全的博客可以满是电话；一篇攻击性文本可以没有 PII。两个过滤器串联，不要合成一个「敏感」分数。</p><p><span class="marginnote">占位符本身会成为高频 token。若每页页脚都变成 <code>&lt;EMAIL&gt;</code>，模型会过度生成该 token。改写后可再跑一遍「占位符密度」启发式，对模板页仍选择丢弃。PII 去除不是把所有页变成带槽位的表格。</span></p><h3 id="评测泄漏与逆向" tabindex="-1">评测泄漏与逆向 <a class="header-anchor" href="#评测泄漏与逆向" aria-label="Permalink to &quot;评测泄漏与逆向&quot;">​</a></h3><p>评测集里若含真实邮箱（少见但有），训练集脱敏会导致「记不住评测实体」，这其实是好事。反过来，若用哈希假名且哈希算法可逆或空间小，攻击者仍可能撞库。不要把「脱敏」理解成密码学保证；它是降低训练记忆与减少无意泄露的工程控制。对极敏感类别（证件扫描 OCR 文本），应整页隔离，而不是相信正则已经完美。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>正则写不全国际化电话与新顶级域名；要按语言桶维护模式库。OCR 与 PDF 抽取会在数字中插入空格与换行，需在 PII 之前做数字串拼接，否则银行卡被拆开漏检。代码许可数据里的作者邮箱是否去除，要与许可证及引用规范一起决定：学术引用需要姓名，不等于需要私人手机。过度 NER 会伤害传记能力与封闭书问答；对人名默认放行、对联系方式默认替换，是常见折中。</p><p>分布式运行时，PII 模型与规则必须版本钉死，输出应保留「匹配类型计数」列供审计，但不要把匹配到的原文 PII 写进明文日志。审计抽样应在受控环境进行。宣称「本语料无 PII」在网页数据上几乎必假；诚实的说法是覆盖了哪些类别、抽样假阳性/假阴性、以及整页丢弃的比例。</p><p><span class="marginnote">指令微调数据常比网页更危险：用户粘贴的工单、病历、聊天记录。网页管道的正则不够用，应对 SFT 语料做更严的一层，甚至人工抽检。不要因为预训练已经「去过 PII」就跳过对齐数据。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PII 去除针对可识别个人的跨度，与毒性、质量过滤分离；优先改写跨度而不是整页删除。</li><li>结构化模式用正则加校验；开放实体用保守 NER 或上下文触发；准标识符组合无法清零。</li><li>应在规范化与改写之后再去重，避免脱敏前后指纹不一致。</li><li>占位符优于随机假号码；共指哈希会保留可链接性。</li><li>命中密度高的页按泄漏/目录处理，整页丢弃。</li><li>不宣称清零；用类别表、抽样误差与日志政策说话。</li><li>出处：Raffel et al., C4；Soldaini et al., Dolma；以及 Presidio 一类 PII 识别工程实践。</li></ul>',12))])}const u=o(I,[["render",P]]);export{_ as __pageData,u as default};
